import pandas as pd
import numpy as np

# Load data
data = pd.read_csv('chunks_csv/bivariate/bivariate_2022_no2_ghg.csv')
adjacency = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Handle missing values in NO2 column by replacing them with the mean of the NO2 values
data['NO2_value'] = data['NO2_value'].fillna(data['NO2_value'].mean())

# Identify neighboring boroughs
adjacency_list = {}
for index, row in adjacency.iterrows():
    if row['borough'] not in adjacency_list:
        adjacency_list[row['borough']] = []
    adjacency_list[row['borough']].append(row['neighbor'])

# Create a spatial correlation matrix
data_points_used = len(data)
spatial_matrix = np.zeros((data_points_used, data_points_used))
for i in range(data_points_used):
    for j in range(data_points_used):
        if i != j:
            if data.loc[i, 'borough'] in adjacency_list and data.loc[j, 'borough'] in adjacency_list:
                spatial_matrix[i, j] = data.loc[i, 'NO2_value'] * data.loc[j, 'GHG_value']

# Compute Lee's L statistic
lee_l_statistic = np.sum(spatial_matrix)

# Permutation test
p_value = 0
for _ in range(500):
    # Shuffle NO2 values
    data_shuffled = data.copy()
    data_shuffled['NO2_value'] = np.random.permutation(data_shuffled['NO2_value'])

    # Create a new spatial correlation matrix
    spatial_matrix_shuffled = np.zeros((data_points_used, data_points_used))
    for i in range(data_points_used):
        for j in range(data_points_used):
            if i != j:
                if data_shuffled.loc[i, 'borough'] in adjacency_list and data_shuffled.loc[j, 'borough'] in adjacency_list:
                    spatial_matrix_shuffled[i, j] = data_shuffled.loc[i, 'NO2_value'] * data_shuffled.loc[j, 'GHG_value']

    # Compute Lee's L statistic for the shuffled data
    lee_l_statistic_shuffled = np.sum(spatial_matrix_shuffled)

    # Update p-value
    if lee_l_statistic_shuffled >= lee_l_statistic:
        p_value += 1

# Determine significance
p_value /= 500
if p_value < 0.05:
    print(f'FINAL ANSWER: POSITIVE (test statistic = {lee_l_statistic}, p = {p_value})')
else:
    print(f'FINAL ANSWER: NOT SIGNIFICANT (test statistic = {lee_l_statistic}, p = {p_value})')

print(f'data_points_used = {data_points_used}')
